// Generated by `uv run python -m app.tools.typescript` (backend/) from the tools' declared result models.
// Don't edit by hand: change the model in backend/app/tools/, then run the command again.

/** One CVE's verdict. */
export interface AffectedOne {
  n: number
  id: string
  product: string
  severity: 'CRITICAL' | 'HIGH' | 'MEDIUM' | 'LOW' | 'NONE' | null
  verdict: 'affected' | 'not_affected' | 'unknown'
  reason: string
  fixed_version: string | null
  who_acts: 'you' | 'upstream' | 'vendor'
  usage: string
  version: string | null
  watch_status: 'open' | 'fixed' | 'not_affected' | 'accepted' | 'not_watched'
  possible_match: boolean
  note: string
}

/** A watched product's open CVEs by verdict. */
export interface AffectedProduct {
  product: string
  usage: string
  version: string | null
  open: number
  counts: VerdictCounts
  cves: AffectedRow[]
  who_acts: 'you' | 'upstream' | 'vendor' | null
  note: string
}

export interface VerdictCounts {
  affected: number
  unknown: number
  not_affected: number
}

export interface AffectedRow {
  id: string
  severity: 'CRITICAL' | 'HIGH' | 'MEDIUM' | 'LOW' | 'NONE' | null
  verdict: 'affected' | 'not_affected' | 'unknown'
  reason: string
  fixed_version: string | null
}

/** lookup_cve: one CVE with its OWASP, KEV, EPSS and watchlist context, the verdict and the priority. */
export interface CveResult {
  n: number
  id: string
  product: string
  published: string
  severity: 'CRITICAL' | 'HIGH' | 'MEDIUM' | 'LOW' | 'NONE' | null
  cvss: number | null
  cwes: string[]
  owasp: Category | null
  description: string
  url: string
  kev: Kev | null
  watch_status: 'open' | 'fixed' | 'not_affected' | 'accepted' | 'not_watched'
  epss: Epss | null
  product_match: 'confirmed' | 'conflicting' | 'unknown' | null
  possible_match: boolean
  verdict: 'affected' | 'not_affected' | 'unknown'
  verdict_reason: string
  fixed_version: string | null
  who_acts: 'you' | 'upstream' | 'vendor'
  no_fix: boolean
  decision: Decision | null
  review_due: boolean
  open_days: number
  priority: Priority | null
}

/** An OWASP Top 10 category. */
export interface Category {
  code: string
  title: string
  url: string
}

export interface Kev {
  date_added: string
  deadline: string
  ransomware: string
  required_action: string
}

export interface Epss {
  score: number
  percentile: number
  date: string
}

/** The user's current decision record (app.status, A16b). */
export interface Decision {
  status: 'open' | 'fixed' | 'not_affected' | 'accepted'
  justification: 'component_not_present' | 'vulnerable_code_not_present' | 'vulnerable_code_not_in_execute_path' | 'vulnerable_code_cannot_be_controlled_by_adversary' | 'inline_mitigations_already_exist' | null
  reason: string | null
  note: string | null
  review_date: string | null
  compensating_control: string | null
  decided_at: string | null
  decided_by: string | null
  via: string | null
  proposal?: string | null
  sources?: ProposalSource[] | null
}

export interface Priority {
  level: 'urgent' | 'high' | 'normal' | 'low'
  reasons: string[]
  due_date: string
  due_from: string
  overdue: boolean
  alert_priority: number
}

/** A source a proposed decision cites (B22): what it rests on, so you can check it before you approve. A web
source is always marked "web result, unverified". */
export interface ProposalSource {
  n: number
  kind: 'knowledge' | 'web'
  label: 'knowledge base' | 'web result, unverified'
  title: string
  url: string
  site: string | null
}

/** update_watchlist (B21) or propose_decision (B22): a proposed change, not made yet. What, why, before and
after, and for a proposed decision the sources it rests on; you approve, edit or cancel it in the chat's card. */
export interface Proposal {
  proposal_id: string
  action: 'watch' | 'unwatch' | 'set_status' | 'set_details'
  title: string
  why: string | null
  cve_id: string | null
  product: string | null
  product_name: string | null
  before: string
  after: string
  fields: ProposalFields
  state: 'proposed' | 'approved' | 'cancelled' | 'expired'
  message: string
  as_of: string
  created_at: string
  expires_at: string
  approved_at: string | null
  approved_by: string | null
  sources: ProposalSource[]
  editable: ('status' | 'justification' | 'note' | 'reason' | 'review_date' | 'compensating_control' | 'usage' | 'version' | 'internet_facing')[]
  link_to: 'cve' | 'watchlist'
}

/** propose_decision when the CVE already has that status: nothing to propose, and why (B27). */
export interface DecisionAlreadySo {
  message: string
}

/** What a proposal would set. Only the fields its action takes are filled; the others are null. */
export interface ProposalFields {
  status: 'open' | 'fixed' | 'not_affected' | 'accepted' | null
  justification: 'component_not_present' | 'vulnerable_code_not_present' | 'vulnerable_code_not_in_execute_path' | 'vulnerable_code_cannot_be_controlled_by_adversary' | 'inline_mitigations_already_exist' | null
  note: string | null
  reason: string | null
  review_date: string | null
  compensating_control: string | null
  usage: 'self_hosted' | 'library' | 'transitive' | 'hosted' | null
  version: string | null
  internet_facing: boolean | null
}

/** prioritise: the top open CVEs in the rules' order, and the view they come from. */
export interface FixFirstResult {
  filters: Filters
  ignored: string[]
  product: string | null
  total_open: number
  cves: FixFirstCve[]
  note: string
}

/** The view's filters that were applied (CveView's names, without status). A filter that isn't set is absent. */
export interface Filters {
  product?: string
  severity?: 'CRITICAL' | 'HIGH' | 'MEDIUM' | 'LOW'
  verdict?: 'affected' | 'not_affected' | 'unknown'
  kev?: boolean
  since?: string
}

export interface FixFirstCve {
  rank: number
  n: number
  id: string
  product: string
  severity: 'CRITICAL' | 'HIGH' | 'MEDIUM' | 'LOW' | 'NONE' | null
  kev: boolean
  epss_percentile: number | null
  verdict: 'affected' | 'not_affected' | 'unknown'
  status: 'open' | 'accepted'
  review_due: boolean
  priority: 'urgent' | 'high' | 'normal' | 'low'
  reasons: string[]
  due_date: string
  due_from: string
  overdue: boolean
  no_fix: boolean
  open_days: number
}

/** search_security: the translated query and the numbered sources. */
export interface SearchResult {
  query: QueryInfo
  sources: FoundSource[]
}

export interface QueryInfo {
  original: string
  semantic_query: string
  rewrites: string[]
  filters: Record<string, string>
  dropped_filters: string[]
  relaxed: boolean
  off_topic?: boolean
  found_by?: Record<string, string[]>
}

/** A numbered source with its full chunk text. A field the chunk doesn't have is absent. */
export interface FoundSource {
  n: number
  doc_id: string
  doc_type: 'owasp_llm' | 'owasp_web' | 'atlas_technique' | 'atlas_mitigation' | 'atlas_case' | 'cve'
  title: string
  section?: string
  date?: string
  product?: string
  severity?: 'CRITICAL' | 'HIGH' | 'MEDIUM' | 'LOW' | 'NONE'
  kev?: boolean
  text: string
}

/** check_updates: this check, or the last one when refused, with what it found for this user. */
export interface UpdatesResult {
  mode: 'live' | 'snapshot'
  as_of: string
  ran: boolean
  refusal: UpdatesRefusal | null
  last_checked: string | null
  trigger: string | null
  ok: boolean | null
  status: 'ok' | 'partial' | 'failed' | null
  problems: string[]
  counts: UpdateCounts
  new_cves: NewCve[]
  alerts: UpdateAlert[]
  alerts_total: number
  schedule: UpdatesSchedule
  note: string
}

export interface UpdatesRefusal {
  reason: 'too_soon' | 'running' | 'snapshot'
  next_allowed: string | null
  message: string
}

export interface UpdateCounts {
  new: number
  updated: number
  kev_added: number
  rescored: number
}

export interface NewCve {
  n: number | null
  id: string
  product: string | null
  severity: 'CRITICAL' | 'HIGH' | 'MEDIUM' | 'LOW' | 'NONE' | null
  kev: boolean
  watched: boolean
  priority: 'urgent' | 'high' | 'normal' | 'low' | null
}

export interface UpdateAlert {
  n: number | null
  cve: string
  reason: string
  priority: number
  held: boolean
}

/** B19: the scheduled check, as the user set it on Settings. */
export interface UpdatesSchedule {
  hours: number
  paused: boolean
  next_due: string | null
}

/** update_watchlist when there's nothing to change (B21): why not, and the watchlist as it is. */
export interface WatchlistResult {
  message: string
  watchlist: string[]
}

/** explain_weakness for a CWE: its OWASP Top 10 category and the snapshot's CVEs with it. */
export interface CweResult {
  kind: 'cwe'
  id: string
  url: string
  category: Category | null
  cves_in_snapshot: number
  examples: CweExample[]
}

/** explain_weakness for an ATLAS technique: tactics, mitigations and the LLM Top 10 risks citing it. */
export interface TechniqueResult {
  kind: 'atlas_technique'
  id: string
  name: string
  url: string
  tactics: string[]
  maturity: string
  description: string
  parent: string | null
  subtechniques: Named[]
  mitigations: Named[]
  cited_by_llm_top10: CitedBy[]
  case_studies: number
}

export interface CweExample {
  id: string
  product: string
  severity: 'CRITICAL' | 'HIGH' | 'MEDIUM' | 'LOW' | 'NONE' | null
}

export interface Named {
  id: string
  name: string
}

export interface CitedBy {
  code: string
  title: string
}

/** research_web: what was searched, how, and the numbered web results. */
export interface ResearchResult {
  query: string
  via: 'mcp' | 'api' | 'canned'
  results: WebHit[]
  flagged: number
  searches_left: number
  note: string
}

/** One web result: a numbered source. */
export interface WebHit {
  n: number
  title: string
  site: string
  url: string
  date: string | null
  snippet: string
  flagged: boolean
}

/** Each tool's result, by the tool's name. */
export interface ToolResults {
  check_affected: AffectedOne | AffectedProduct
  lookup_cve: CveResult
  propose_decision: Proposal | DecisionAlreadySo
  prioritise: FixFirstResult
  search_security: SearchResult
  check_updates: UpdatesResult
  update_watchlist: Proposal | WatchlistResult
  explain_weakness: CweResult | TechniqueResult
  research_web: ResearchResult
}

export type ToolName = keyof ToolResults

/** A tool call's name and result together: check the name, and the result has that tool's type. An unknown tool's
 *  call never has a result. */
export type NamedResult =
  | { [K in ToolName]: { name: K; result: ToolResults[K] | null } }[ToolName]
  | { name: string; result: null }
